import React, { useRef, useEffect } from "react";
import { emojify } from "../../../js/Chat/Emoji/EmojiParser.js";

export default function EmojiInput({ value, onChange, placeholder }) {
  const divRef = useRef(null);

  // Atualiza visual quando o estado muda externamente
  useEffect(() => {
    const html = emojify(value);
    if (divRef.current && divRef.current.innerHTML !== html) {
      divRef.current.innerHTML = html;
    }
  }, [value]);

  // Captura digitação
  const handleInput = () => {
    const text = divRef.current.innerText; // texto puro
    onChange(text);
  };

  // ENTER = enviar, SHIFT+ENTER = nova linha
  const handleKeyDown = (e) => {
    if (e.key === "Enter" && !e.shiftKey) {
      e.preventDefault();
      const event = new CustomEvent("emoji-input-enter");
      divRef.current.dispatchEvent(event);
    }
  };

  return (
    <div
      ref={divRef}
      contentEditable
      onInput={handleInput}
      onKeyDown={handleKeyDown}
      data-placeholder={placeholder || "Mensagem..."}
      style={{
        flex: 1,
        padding: "12px 14px",
        border: "1px solid #ccc",
        borderRadius: "20px",
        minHeight: "20px",
        maxHeight: "200px",
        overflowY: "auto",
        outline: "none",
        whiteSpace: "pre-wrap",
        fontSize: "15px",
        fontFamily: `"Segoe UI Emoji", "Apple Color Emoji", "Noto Color Emoji", sans-serif`
      }}
    />
  );
}
